def _validate_request(data, auth_token):
    """Validate the parts of a request required before processing it."""
    # Authenticate first so unauthenticated callers cannot reach payload handling.
    if not is_valid_token(auth_token):
        raise PermissionError("invalid auth token")

    # An empty mapping or sequence may be a valid payload; only a missing payload
    # is rejected here. More specific validation belongs to ``process``.
    if data is None:
        raise ValueError("request data is required")


def handle_request(data, auth_token):
    """Validate, authenticate, and process an incoming API request."""
    _validate_request(data, auth_token)
    return process(data)

